inline constexpr int kTextKeyCount = 588;

struct TextKeyInfo {
    const char *name;
    bool glyphs;      // a battle-popup glyph list (16-bit codes, 0xFFFF-terminated), else 0xFF-terminated text
    uint32_t site;    // ROM offset of the code operand holding the string's offset
    uint16_t segment; // the segment that offset is relative to
    uint32_t string;  // ROM offset of the original string
    uint16_t length = 0; // > 0: exactly this many characters, no terminator (a name-entry sheet)
};

extern const TextKeyInfo kTextKeys[kTextKeyCount];
// A field dialogue run: ROM range [start, end) of an event script's text;
// its key is dlg_<start in hex>.
struct DialogueRun {
    uint32_t start, end;
};
inline constexpr int kDialogueRunCount = 298;
extern const DialogueRun kDialogueRuns[kDialogueRunCount];

// A battle-popup message: its parts joined with + (fragment keys, R:XXXX for
// a RAM buffer), the routine that shows it, and its key in the text files (msg_<routine>[_n];
// msg:<parts> is accepted too).
struct TextMessage {
    const char *parts;
    const char *routine;
    const char *key;
    int japanese_break = 0; // parts before the original second popup
};
inline constexpr int kTextMessageCount = 107;
extern const TextMessage kTextMessages[kTextMessageCount];

struct CharsetEntry {
    uint8_t code;
    const char *utf8;
};
inline constexpr int kSystemCharsetSize = 210;
extern const CharsetEntry kSystemCharset[kSystemCharsetSize];


